            Dictionary<string, object> Output = new Dictionary<string, object>();
            var serviceProvider = (IServiceProvider)Input["ServiceProvider"];

            // Parse Integration Entry
            IIntegrationEntry iEntry = null;
            if (Input.ContainsKey("IntegrationEntryId"))
            {
                iEntry = serviceProvider.GetService<IIntegrationEntry>();
                iEntry.Load(long.Parse((string)Input["IntegrationEntryId"]));
                iEntry.LoadIntegrationMessage();
            }
            else if (Input.ContainsKey("IntegrationEntry"))
            {
                iEntry = Input["IntegrationEntry"] as IIntegrationEntry;
            }

            if (iEntry == null || iEntry.IntegrationMessage == null || iEntry.IntegrationMessage.Message == null
                || iEntry.IntegrationMessage.Message.Length == 0)
            {
                throw new MissingMandatoryPropertyCmfException("IntegrationMessage", "IntegrationEntry");
            }

            if (string.IsNullOrWhiteSpace(iEntry.MessageType))
            {
                throw new MissingMandatoryPropertyCmfException("MessageType", "IntegrationEntry");
            }

            // Check which action should be called by message type
            if (iEntry.MessageType != "AppFrameworkCreateAndPerformMasterData")
            {
                throw new NotImplementedException("Message Type not supported");
            }

            // Retrieve access token with AppFramework's scope using Client Credentials
            string accessToken;
            try
            {
                using (var spc = new SecurityPortalClient())
                {
                    accessToken = spc.GetClientCredentialsAccessToken(true);
                }
            }
            catch (Exception ex)
            {
                throw new CmfBaseException(string.Format("Error retrieving Access Token from Security Portal. Error message: {0}", ex.Message));
            }

            // Form input object
            string appClientId = serviceProvider.GetService<Cmf.Foundation.Common.Abstractions.IUtilities>().GetAuthSecretProvider().GetClientId();

            var input = new AppFrameworkCreateAndPerformMasterDataPackageInput()
            {
                Name = "AppFrameworkCreateAndPerformMasterData_" + appClientId,
                Description = "Master Data Package required by App " + appClientId,
                MasterDataPackageFile = iEntry.IntegrationMessage.Message
            };
            var jsonStringInput = SerializationSettings.JsonSerializer(input);

            var appFrameworkAddress = serviceProvider.GetService<IAppSettings>()[Constants.APP_FRAMEWORK_ADDRESS];

            // Make request to App Framework
            using HttpContent requestContent = new StringContent(jsonStringInput, Encoding.UTF8, "application/json");
            using HttpClient client = new HttpClient();
            client.BaseAddress = new Uri(appFrameworkAddress);

            using HttpRequestMessage request = new HttpRequestMessage();
            // App framework host will always have this URL within the same network
            request.RequestUri = new Uri("api/MasterData/AppFrameworkCreateAndPerformMasterDataPackage", UriKind.Relative);
            request.Method = HttpMethod.Post;
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", accessToken);
            request.Content = requestContent;

            using HttpResponseMessage reply = client.SendAsync(request).Result;
            // Parse successful request
            if (reply.IsSuccessStatusCode)
            {
                string output = reply.Content.ReadAsStringAsync().Result;
                JObject outputObj = JObject.Parse(output);

                if (outputObj.TryGetValue("Message", out var outputMessage))
                {
                    Output.Add("Result", string.Format("Successful App Framework request with message: {0}", outputMessage.Value<string>()));
                }
                else
                {
                    Output.Add("Result", "Successful App Framework request, but response Message could not be extracted from response.");
                }

                return Output;
            }

            // Try to parse error
            string errorMessage = null;
            try
            {
                string output = reply.Content.ReadAsStringAsync().Result;
                JObject outputObj = JObject.Parse(output);
                if (outputObj.TryGetValue("error", out JToken error) && error != null)
                {
                    errorMessage = error.Value<string>();
                }
            }
            catch
            {
                // we were unable to extract the error as text. Throw the default exception
                reply.EnsureSuccessStatusCode();
            }

            if (!string.IsNullOrEmpty(errorMessage))
            {
                throw new CmfBaseException(errorMessage);
            }

            // If no error could be extracted then throw standard exception
            reply.EnsureSuccessStatusCode();

            return Output; // Should never reach this part
